    private static final long serialVersionUID = -51788488328591145L;
    public BlockPos pos;
    public InteractionHand hand;

    public HarvestMessage() {
    }

    public HarvestMessage(BlockPos pos, InteractionHand hand) {
        this.pos = pos;
        this.hand = hand;
    }

    public boolean receive(IZetaNetworkEventContext context) {
        context.enqueueWork(() -> {
            ServerPlayer player = context.getSender();
            if (player != null) {
                BlockHitResult pick = Item.m_41435_((Level)player.m_9236_(), (Player)player, (ClipContext.Fluid)ClipContext.Fluid.ANY);
                SimpleHarvestModule.click((Player)context.getSender(), this.hand, this.pos, pick);
            }
        });
        return true;
    }
}

